if '## \u06f5\u06f4. \u0627\u062a\u0635\u0627\u0644 \u0634\u0631\u0627\u06cc\u0637' in s:
    print('CLI TP section already present. No changes made.')
else:
    if '\u0646\u0633\u062e\u0647\u0654 \u0633\u0646\u062f: \u06f0\u066b\u06f2\u06f9' not in s:
        raise SystemExit('Expected guide version 0.29 not found. No changes made.')
    s=s.replace('\u0646\u0633\u062e\u0647\u0654 \u0633\u0646\u062f: \u06f0\u066b\u06f2\u06f9','\u0646\u0633\u062e\u0647\u0654 \u0633\u0646\u062f: \u06f0\u066b\u06f3\u06f0',1)+'\n## \u06f5\u06f4. \u0627\u062a\u0635\u0627\u0644 \u0634\u0631\u0627\u06cc\u0637 \u062f\u0645\u0627\u2013\u0641\u0634\u0627\u0631 \u0628\u0647 \u0631\u0627\u0628\u0637 \u062a\u0639\u0627\u0645\u0644\u06cc\n\n\u06af\u0627\u0645 \u0642\u0628\u0644\u06cc \u0631\u0648\u06cc \u0644\u067e\u200c\u062a\u0627\u067e \u0628\u0627 \u06f5\u06f5 \u0622\u0632\u0645\u0648\u0646 \u0645\u0648\u0641\u0642 \u062f\u0631 \u06f0\u066b\u06f0\u06f6\u06f0 \u062b\u0627\u0646\u06cc\u0647 \u062a\u0623\u06cc\u06cc\u062f \u0648 \u0628\u0627 commit \u0634\u0645\u0627\u0631\u0647\u0654 71ab573 \u062b\u0628\u062a \u0648 \u0627\u0631\u0633\u0627\u0644 \u0634\u062f. \u0634\u0627\u062e\u0647\u0654 stage-2-mixture \u0647\u0645\u06af\u0627\u0645 \u0648 \u067e\u0648\u0634\u0647\u0654 \u06a9\u0627\u0631\u06cc \u067e\u0627\u06a9 \u0628\u0648\u062f.\n\n\u062f\u0631 \u06af\u0627\u0645 \u062c\u062f\u06cc\u062f\u060c read_conditions \u0628\u0647 cli.py \u0627\u0636\u0627\u0641\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f. \u067e\u0633 \u0627\u0632 \u062f\u0631\u06cc\u0627\u0641\u062a \u062a\u0631\u06a9\u06cc\u0628\u060c \u06a9\u0627\u0631\u0628\u0631 \u0648\u0627\u062d\u062f \u062f\u0645\u0627 (K/C)\u060c \u0645\u0642\u062f\u0627\u0631 \u062f\u0645\u0627\u060c \u0648\u0627\u062d\u062f \u0641\u0634\u0627\u0631 \u0645\u0637\u0644\u0642 (Pa/bar) \u0648 \u0645\u0642\u062f\u0627\u0631 \u0641\u0634\u0627\u0631 \u0631\u0627 \u0648\u0627\u0631\u062f \u0645\u06cc\u200c\u06a9\u0646\u062f. \u0645\u0642\u062f\u0627\u0631 \u0646\u0627\u0645\u0639\u062a\u0628\u0631 \u0628\u0627\u0639\u062b \u062a\u06a9\u0631\u0627\u0631 \u067e\u0631\u0633\u0634 \u0647\u0645\u0627\u0646 \u0628\u062e\u0634 \u0645\u06cc\u200c\u0634\u0648\u062f. \u062a\u063a\u06cc\u06cc\u0631 \u0648\u0627\u062d\u062f \u062f\u0645\u0627 \u062f\u0631 \u0647\u0631 \u062a\u0644\u0627\u0634 \u0645\u062c\u062f\u062f \u0635\u0631\u06cc\u062d \u0627\u0633\u062a\u061b \u062f\u0645\u0627\u06cc \u0645\u0639\u062a\u0628\u0631 \u067e\u0633 \u0627\u0632 \u0622\u0646 \u062d\u0641\u0638 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0627\u0635\u0644\u0627\u062d \u0641\u0634\u0627\u0631 \u0646\u06cc\u0627\u0632\u0645\u0646\u062f \u0648\u0631\u0648\u062f \u062f\u0648\u0628\u0627\u0631\u0647\u0654 \u062a\u0631\u06a9\u06cc\u0628 \u06cc\u0627 \u062f\u0645\u0627 \u0646\u06cc\u0633\u062a.\n\n\u062a\u0628\u062f\u06cc\u0644 \u0628\u0627 TPConditions.from_units \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f. \u0628\u0631\u0627\u06cc \u0627\u0639\u062a\u0628\u0627\u0631\u0633\u0646\u062c\u06cc \u0627\u0648\u0644\u06cc\u0647\u0654 \u062f\u0645\u0627\u060c \u0641\u0634\u0627\u0631 \u0645\u062b\u0628\u062a \u0646\u0645\u0648\u0646\u0647\u0654 \u06f1 \u067e\u0627\u0633\u06a9\u0627\u0644 \u0641\u0642\u0637 \u062f\u0631 \u0641\u0631\u0627\u062e\u0648\u0627\u0646 \u062f\u0627\u062e\u0644\u06cc \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u0627\u06cc\u0646 \u0645\u0642\u062f\u0627\u0631 \u0634\u0631\u0627\u06cc\u0637 \u0648\u0627\u0642\u0639\u06cc \u062e\u0648\u0631\u0627\u06a9 \u0646\u06cc\u0633\u062a. \u0647\u0646\u06af\u0627\u0645 \u062f\u0631\u06cc\u0627\u0641\u062a \u0641\u0634\u0627\u0631\u060c \u0634\u06cc\u0621 \u0646\u0647\u0627\u06cc\u06cc \u0628\u0627 \u062f\u0645\u0627\u06cc \u0645\u0639\u062a\u0628\u0631 \u0648 \u0641\u0634\u0627\u0631 \u0648\u0627\u0642\u0639\u06cc \u06a9\u0627\u0631\u0628\u0631 \u0633\u0627\u062e\u062a\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f. \u0648\u0627\u062d\u062f bar \u062f\u0631 \u0627\u06cc\u0646 \u0631\u0627\u0628\u0637 \u0641\u0642\u0637 \u0641\u0634\u0627\u0631 \u0645\u0637\u0644\u0642 \u0627\u0633\u062a\u061b \u0648\u0627\u062d\u062f barg \u0631\u062f \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0645\u0642\u062f\u0627\u0631 \u0639\u062f\u062f\u06cc \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u0645\u0628\u0646\u0627\u06cc \u0641\u0634\u0627\u0631 \u0631\u0627 \u0622\u0634\u06a9\u0627\u0631 \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f.\n\nEOF \u06cc\u0627 Ctrl+C \u0628\u0647 \u0645\u062f\u06cc\u0631\u06cc\u062a \u0644\u063a\u0648 \u0645\u0648\u062c\u0648\u062f \u062f\u0631 main \u0645\u06cc\u200c\u0631\u0633\u0646\u062f. \u062e\u0631\u0648\u062c\u06cc \u0634\u0627\u0645\u0644 \u062a\u0631\u06a9\u06cc\u0628\u060c \u062f\u0645\u0627\u06cc K \u0648 \u0641\u0634\u0627\u0631 Pa \u0627\u0633\u062a. \u0647\u0646\u0648\u0632 \u0645\u062d\u0627\u0633\u0628\u0647\u0654 \u0641\u0644\u0634 \u0627\u0646\u062c\u0627\u0645 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f.\n\n\u0627\u0633\u06a9\u0631\u06cc\u067e\u062a connect_tp_cli.py \u0628\u0627 \u062a\u0637\u0628\u06cc\u0642 \u062f\u0642\u06cc\u0642 \u0686\u0647\u0627\u0631 \u0645\u062d\u0644 \u062f\u0631 cli.py \u062a\u063a\u06cc\u06cc\u0631 \u0631\u0627 \u0627\u0639\u0645\u0627\u0644 \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0627\u06af\u0631 \u0633\u0627\u062e\u062a\u0627\u0631 \u0645\u062a\u0641\u0627\u0648\u062a \u06cc\u0627 \u0642\u0628\u0644\u0627\u064b \u0627\u0635\u0644\u0627\u062d \u0634\u062f\u0647 \u0628\u0627\u0634\u062f\u060c \u0628\u062f\u0648\u0646 \u0646\u0648\u0634\u062a\u0646 \u0641\u0627\u06cc\u0644 \u0645\u062a\u0648\u0642\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f. tests/test_cli_conditions.py \u0633\u0647 \u0622\u0632\u0645\u0648\u0646 \u062f\u0627\u0631\u062f: \u062a\u0628\u062f\u06cc\u0644 \u0635\u062d\u06cc\u062d\u060c \u0628\u0627\u0632\u06cc\u0627\u0628\u06cc \u067e\u0633 \u0627\u0632 \u0648\u0631\u0648\u062f\u06cc\u200c\u0647\u0627\u06cc \u0646\u0627\u0645\u0639\u062a\u0628\u0631 \u0648 \u0627\u0646\u062a\u0642\u0627\u0644 EOF \u0628\u0647 \u0645\u062f\u06cc\u0631\u06cc\u062a \u0644\u063a\u0648. \u0628\u0627 \u06f5\u06f5 \u0622\u0632\u0645\u0648\u0646 \u0642\u0628\u0644\u06cc\u060c \u0627\u0646\u062a\u0638\u0627\u0631 \u06f5\u06f8 \u0622\u0632\u0645\u0648\u0646 \u0627\u0633\u062a. \u0645\u0648\u0641\u0642\u06cc\u062a \u0631\u0648\u06cc \u0644\u067e\u200c\u062a\u0627\u067e \u0647\u0646\u0648\u0632 \u0628\u0627\u06cc\u062f \u06af\u0632\u0627\u0631\u0634 \u0634\u0648\u062f.\n\n\u0646\u0645\u0648\u0646\u0647\u0654 \u0627\u062c\u0631\u0627\u06cc \u062a\u0639\u0627\u0645\u0644\u06cc: \u062a\u0631\u06a9\u06cc\u0628 \u062f\u0644\u062e\u0648\u0627\u0647\u060c \u062f\u0645\u0627\u06cc \u06f2\u06f5 C\u060c \u0641\u0634\u0627\u0631 \u06f1\u06f0 bar \u0645\u0637\u0644\u0642\u061b \u062e\u0631\u0648\u062c\u06cc \u0645\u0648\u0631\u062f \u0627\u0646\u062a\u0638\u0627\u0631 298.15 K \u0648 1000000 Pa \u0627\u0633\u062a. \u0646\u0633\u062e\u0647\u0654 \u0631\u0627\u0647\u0646\u0645\u0627 \u062f\u0631 \u0627\u06cc\u0646 \u06af\u0627\u0645 \u06f0\u066b\u06f3\u06f0 \u0645\u06cc\u200c\u0634\u0648\u062f.\n'
    p.write_text(s,encoding='utf-8')
    print('Guide updated to 0.30.')
